// UpdateThirdPartyPrivacyEvaluation is the resolver for the updateThirdPartyPrivacyEvaluation field.
func (r *mutationResolver) UpdateThirdPartyPrivacyEvaluation(ctx context.Context, input types.UpdateThirdPartyPrivacyEvaluationInput) (*types.UpdateThirdPartyPrivacyEvaluationPayload, error) {
	scope, err := r.authorize(ctx, input.RiskAssessmentID, probo.ActionThirdPartyRiskAssessmentCreate)
	if err != nil {
		return nil, err
	}

	// Choosing the evaluator and approver needs to see the members.
	if _, err := r.authorize(ctx, input.RiskAssessmentID, iam.ActionMembershipProfileList); err != nil {
		return nil, err
	}

	req, err := newUpdateThirdPartyPrivacyEvaluationRequest(input)
	if err != nil {
		return nil, r.thirdPartyEvaluationError(ctx, err, "")
	}

	if err := r.probo.ThirdPartyPrivacyEvaluations.Update(ctx, scope, req); err != nil {
		return nil, r.thirdPartyEvaluationError(ctx, err, "cannot update third party privacy evaluation")
	}

	assessment, err := r.probo.ThirdParties.GetRiskAssessment(ctx, scope, input.RiskAssessmentID)
	if err != nil {
		r.logger.ErrorCtx(ctx, "cannot get third party risk assessment", log.Error(err))
		return nil, gqlutils.Internal(ctx)
	}

	return &types.UpdateThirdPartyPrivacyEvaluationPayload{
		ThirdPartyRiskAssessment: types.NewThirdPartyRiskAssessment(assessment),
	}, nil
}

// ExportThirdPartyEvaluationSheet is the resolver for the exportThirdPartyEvaluationSheet field.
func (r *mutationResolver) ExportThirdPartyEvaluationSheet(ctx context.Context, input types.ExportThirdPartyEvaluationSheetInput) (*types.ExportThirdPartyEvaluationSheetPayload, error) {
	// The sheet lists the risk assessments, the register entries outsourced
	// to each third party and the names of evaluators and approvers besides
	// the third parties.
	for _, action := range []string{
		probo.ActionThirdPartyRiskAssessmentList,
		probo.ActionProcessingActivityList,
		iam.ActionMembershipProfileList,
	} {
		if _, err := r.authorize(ctx, input.OrganizationID, action); err != nil {
			return nil, err
		}
	}

	scope, err := r.authorize(ctx, input.OrganizationID, probo.ActionThirdPartyList)
	if err != nil {
		return nil, err
	}

	workbook, err := r.probo.ThirdPartyPrivacyEvaluations.Export(ctx, scope, input.OrganizationID)
	if err != nil {
		r.logger.ErrorCtx(ctx, "cannot export outsourcing evaluation", log.Error(err))
		return nil, gqlutils.Internal(ctx)
	}

	return &types.ExportThirdPartyEvaluationSheetPayload{
		Data: fmt.Sprintf("data:%s;base64,%s", xlsxexport.ContentType, base64.StdEncoding.EncodeToString(workbook)),
	}, nil
}

